if PI<=0 or(MI or 0)<=0 then
return 0,0
end
local QI=math.min(MI,PI)
local RI=db.base(LI)
if RI<=0 then
return 0,QI
end
return db.share(LI.unit_id)*(db.score(db.whatIf(LI,{xp=NI+QI}))/RI-1)*100,QI
end
function db.gainFuse(SI)
