local VI=db.whatIf(SI,{xp=math.max(tonumber(SI.xp)or 0,db.xpFor(SI.unit_id,110)),further_modifiers={limit_break={current_limit_break=1}}})
return db.share(SI.unit_id)*(db.score(VI)/TI-1)*100+5
end
