W.INF_CAP=80
function W.evaluate(_mb,anb)
local bnb=W.run(_mb,anb,{hpMul=1})
local cnb={won=bnb.won,wave=bnb.wave,minutes=bnb.t/60,aliveAt=bnb.aliveAt,total=_mb.total,at=os.time()}
if _mb.infinite and W.unbound(_mb.ld)then
cnb.p=1
