elseif bnb.won then
local dnb=W.run(_mb,anb,{hpMul=1.3})
cnb.p=dnb.won and 0.92 or 0.7
cnb.margin=dnb.won and Nuc[2646]or Nuc[2647]
else
local enb=W.run(_mb,anb,{hpMul=0.75})
cnb.p=enb.won and 0.25 or 0.05
