end
function W.trust(gnb,hnb)
local inb=gnb.cal or{}
if type(inb.alive)~=Nuc[1440]or inb.teamSig~=W.sig((function()
local jnb={}
for knb,lnb in ipairs(hnb)do
table.insert(jnb,lnb.u)
end
return jnb
end)())then
return nil
end
if gnb.key==Nuc[1734]and not inb.aliveLvl then
return nil
end
if inb.aliveLvl and gnb.ld and gnb.ld.id and inb.aliveLvl~=tostring(gnb.ld.id)..(eb.is(gnb.ld.id)and(Nuc[2651]..tostring(gnb.ld.map))or Nuc[369])then
return nil
end
local mnb=W.run(gnb,hnb,{hpMul=1})
local nnb,onb,pnb=0,0,0
for qnb=3,math.min(mnb.wave,tonumber(inb.lastWave)or 99)do
local rnb=tonumber(inb.alive[tostring(qnb)])
local snb=mnb.aliveAt[qnb]
if rnb and snb and rnb>0 then
nnb=nnb+rnb
onb=onb+snb
pnb=pnb+1
end
end
if pnb<2 or onb<=0 then
return nil
end
local tnb=nnb/onb
return{ratio=tnb,ok=tnb>=0.75 and tnb<=1.33,waves=pnb}
end
W.GROWN_LEVEL,W.GROWN_MIN=50,6
function W.grownKinds()
