if not vnb[znb]and H.Units[znb]and not N.isFarm(znb)and N.rows(znb)and not N.hidden(znb)then
local Anb,Bnb=pcall(H.USC.calculate_level,znb,tonumber(ynb.xp)or 0)
if Anb and(tonumber(Bnb)or 0)>=W.GROWN_LEVEL then
vnb[znb]=true
wnb=wnb+1
end
end
end
return wnb
end
function W.pool(Cnb,Dnb)
local Enb=H.session()
local Fnb,Gnb={},{}
local Hnb=W.grownKinds()>=W.GROWN_MIN
for Inb,Jnb in pairs(Enb.profile_data.collection.owned_units)do
local Knb=Enb.collection:get_unit_by_uuid(Jnb.uuid)or Jnb
local Lnb,Mnb=pcall(H.USC.calculate_level,Knb.unit_id,tonumber(Knb.xp)or 0)
local Nnb=N.isFarm(Knb.unit_id)or not Hnb or(Lnb and(tonumber(Mnb)or 0)>=W.GROWN_LEVEL)
if H.Units[Knb.unit_id]and N.rows(Knb.unit_id)and not N.hidden(Knb.unit_id)and Nnb then
local Onb=N.isFarm(Knb.unit_id)
local Pnb,Qnb=pcall(Onb and function()
return N.farm(Knb,N.rows(Knb.unit_id).max)
end or N.score,Knb,Cnb)
Qnb=(Pnb and Qnb or 0)*(Onb and 1 or N.skinMul(Knb,Dnb and Dnb.skinSet))
local Rnb=Onb and Gnb or Fnb
if not Rnb[Knb.unit_id]or Qnb>Rnb[Knb.unit_id].sc then
