end
table.sort(Snb,function(Ynb,Znb)
return Ynb.sc>Znb.sc
end)
table.sort(Tnb,function(_nb,aob)
return _nb.sc>aob.sc
end)
local bob={}
for cob=1,math.min(10,#Snb)do
table.insert(bob,Snb[cob].u)
end
local dob,eob={},{}
for fob=11,#Snb do
local gob=N.rows(Snb[fob].u.unit_id)
for hob=0,gob.max do
if gob[hob]and gob[hob].atk and N.attackInfo(gob[hob].atk,gob[hob].range).dot>0 then
table.insert(hob==0 and dob or eob,Snb[fob].u)
