end
end
end
for iob=1,math.min(4,#dob)do
table.insert(bob,dob[iob])
end
for job=1,math.min(2,#eob)do
table.insert(bob,eob[job])
end
for kob=1,math.min(3,#Tnb)do
table.insert(bob,Tnb[kob].u)
end
local lob={}
for mob=11,#Snb do
local nob=N.rows(Snb[mob].u.unit_id)[0]
local oob=nob and nob.atk and N.attackInfo(nob.atk,nob.range)
if oob and(oob.slowTime>0 or oob.stun>0)then
table.insert(lob,Snb[mob].u)
end
end
for pob=1,math.min(3,#lob)do
table.insert(bob,lob[pob])
end
for qob=11,#Snb do
local rob=Snb[qob].u.unit_id
if N.allyBuff(rob)or N.BLESS.by[rob]or N.GALE[rob]then
table.insert(bob,Snb[qob].u)
end
end
if Dnb and((Dnb.flyChance or 0)>0 or Dnb.mapFly or(Dnb.shield or 0)>0)then
local sob,tob={},{}
for uob=11,#Snb do
local vob=Snb[uob].u
local wob=N.rows(vob.unit_id)[0]
if N.airFrom(vob.unit_id)==0 then
table.insert(sob,vob)
end
local xob,yob=tonumber(wob and wob.cd)or 0,tonumber((H.Units[vob.unit_id]or{}).cost)or 0
if xob>0 and yob>0 and N.range(vob,0)>=15 then
local zob=N.attackInfo(wob.atk,wob.range)
table.insert(tob,{u=vob,v=zob.n*zob.hits/xob/yob*math.min(6,N.cap(vob))})
end
end
table.sort(tob,function(Aob,Bob)
return Aob.v>Bob.v
end)
for Cob=1,math.min(4,#sob)do
table.insert(bob,sob[Cob])
end
for Dob=1,math.min(6,#tob)do
table.insert(bob,tob[Dob].u)
end
end
local Eob,Fob={},{}
for Gob,Hob in ipairs(bob)do
if not Eob[Hob]then
Eob[Hob]=true
table.insert(Fob,Hob)
end
end
Fob.rest={}
for Iob,Job in ipairs(Snb)do
if not Eob[Job.u]then
table.insert(Fob.rest,Job.u)
end
end
return Fob
end
function W.objective(Kob)
