end
local jpb=J.modes[dpb.key]
local kpb=jpb and tonumber(jpb.streak)or 0
if not hpb and jpb and(tonumber(jpb.wins)or 0)>0 and kpb==0 and dpb.key~=Nuc[1734]and dpb.key~=Nuc[1730]then
