local bwb=cb.res(Zvb)
local cwb=cb.rooms(Zvb)
local dwb={}
for ewb,fwb in ipairs(cwb)do
table.insert(dwb,tostring(fwb.r._r))
end
local gwb=table.concat(dwb,Nuc[2036])..string.format(Nuc[2738],awb,bwb,_vb,O.teamSig())
if cb._pick and cb._pick.sig==gwb then
return cb._pick.x
end
local hwb,iwb
for jwb,kwb in ipairs(cwb)do
local lwb=cb.roomValue(kwb,bwb)
local mwb,nwb
for owb,pwb in ipairs(cb.after(Zvb,kwb.choice))do
local qwb=cb.roomValue(pwb,bwb)
if not mwb or qwb>mwb then
mwb,nwb=qwb,pwb
end
end
local rwb,swb=cb.winP(kwb)
local twb=1-(1-rwb)^math.max(1,awb)
local uwb=awb>=3 and 1 or(awb==2 and 2 or 6)
kwb.p,kwb.sim,kwb.value,kwb.nextValue,kwb.nextRoom=rwb,swb,lwb,mwb or 0,nwb
kwb.score=twb*(lwb+0.6*(mwb or 0))-(1-rwb)*uwb
local vwb,wwb,xwb=pcall(cb.curseGate,kwb,Zvb)
if vwb and not wwb then
kwb.blocked=xwb
end
if not kwb.blocked and(not hwb or kwb.score>hwb.score)then
hwb=kwb
end
if not iwb or kwb.score>iwb.score then
iwb=kwb
end
end
hwb=hwb or iwb
cb._pick={sig=gwb,x=hwb,rooms=cwb}
return hwb
end
