local vxb=cb.res(sxb)
local wxb=1+0.1*(cb.items(sxb)._curse_shop or 0)
local xxb=cb.shopAhead(sxb)and math.ceil(cb.LUCK_RESERVE*wxb)or 0
local yxb={}
local zxb,Axb={},0
for Bxb,Cxb in ipairs(cb.offers(txb and txb.data))do
Cxb.cost=math.ceil(Cxb.cost*wxb)
table.insert(zxb,tostring(cb.item(Cxb.id).name or Cxb.id))
if not Cxb.bought and not cb.isCurse(Cxb.id)then
Cxb.luck=tonumber(cb.item(Cxb.id).luck_increase)~=nil
Cxb.v=cb.itemValue(Cxb.id,sxb)
if not Cxb.luck and Cxb.v/math.max(1,Cxb.cost)<cb.MIN_WORTH then
Axb=Axb+1
